    {"대지": "서론", "내용": "거짓 교사들은 율법의 선생이 되려는 야망은 있었으나 그들이 말하는 것의 본질은 몰랐다. 바울은 이 이중적 무지를 폭로한다", "예화_적용": "지도를 못 읽으면서 길잡이가 되려는 사람은 자신뿐 아니라 따르는 자도 잃게 한다"},
    {"대지": "1대지: 되려 하는 야망 (직분에 대한 갈망)", "내용": "그들은 율법의 선생이 되려 했다. 섬기려는 것이 아닌 되려는 것이 문제였다. 직분에 대한 야망이 먼저 앞섰다", "예화_적용": "등산가가 정상에 오르려는 욕심에 장비도 없이 오르면 위험하다. 준비 없이 직분에 오르는 자도 마찬가지이다"},
    {"대지": "2대지: 말하는 것을 알지 못함 (내용의 결핍)", "내용": "그들은 자신이 하는 말의 본뜻을 몰랐다. 용어는 익숙하나 내용은 비어 있었다. 앵무새식 반복에 그쳤다", "예화_적용": "외운 문장을 반복하는 앵무새는 의미를 모른다. 복음을 의미 없이 반복하면 앵무새와 다름없다"},
    {"대지": "3대지: 확증하는 것도 알지 못함 (확신의 거짓)", "내용": "그들은 강하게 주장했지만 주장하는 내용도 몰랐다. 확신의 목소리와 진리의 내용은 다르다", "예화_적용": "빈 수레가 더 요란하다. 내용이 없을수록 목소리가 커진다"},
    {"대지": "결론", "내용": "가르치는 자리는 무거운 자리이다. 먼저 배워야 한다. 야망이 아닌 섬김으로, 확신의 목소리가 아닌 진리의 내용으로 사역하자", "예화_적용": "깊은 우물에서만 깊은 물을 길을 수 있다. 깊이 배운 자만 깊이 가르칠 수 있다"}
