    {"원어": "νομίμως (노미모스)", "의미_문법": "합당하게 - 부사. 법답게, 본래 의도에 맞게", "설교포인트": "율법은 바르게 사용될 때만 유익하다. 합당한 사용이 율법의 가치를 드러낸다"}
