    {"교리": "의인과 율법", "설명": "성령으로 거듭난 의인은 내면에서 법을 사랑한다. 외적 강제가 아닌 내면의 동기로 하나님의 뜻을 따른다", "관련구절": "렘 31:33, 겔 36:27, 롬 8:4, 시 119:97"}
