    {"원어": "διώκτην (디오크텐)", "의미_문법": "핍박자 - 명사 남성 단수 대격. 박해하여 쫓는 자", "설교포인트": "바울은 교회를 핍박했다. 사울이란 이름으로 알려진 극렬한 핍박자였다"},
    {"원어": "ἠλεήθην (엘레에텐)", "의미_문법": "긍휼을 입다 - 동사 아오리스트 수동 직설법 1인칭 단수. 자비를 받다", "설교포인트": "긍휼이 바울 간증의 중심 단어이다. 자격 없는 자에게 주어진 자비가 그의 정체성을 바꾸었다"}
