    {"상황": "한때 신앙이 뜨거웠으나 지금은 차가워진 분", "성경원리": "믿음은 순간에 식지 않는다. 양심의 작은 타협이 누적된 결과이다. 어디서부터 구멍이 생겼는지 점검해야 한다", "실제적용": "언제부터 믿음이 식었는지 돌아보고 양심의 회복을 위한 구체적 회개와 순종을 시작하도록 안내하라"}
