    {"교리": "진리와 구원의 관계", "설명": "구원은 진리의 인식과 함께 온다. 믿음의 내용이 중요하다. 무지한 경건은 참된 구원이 아니다", "관련구절": "요 8:32, 요 17:3, 딤후 3:7"}
