    {"원어": "ἄνθρωπος (안트로포스)", "의미_문법": "사람 - 명사 남성 단수 주격. 인간", "설교포인트": "그리스도는 참 사람이시다. 이 인성이 중보의 근거이다. 사람만이 사람의 입장을 대변할 수 있다"}
