    {"원어": "ὑπὲρ πάντων (휘페르 판톤)", "의미_문법": "모든 사람을 위하여 - 전치사 + 형용사 복수 속격. 대신하여", "설교포인트": "속전의 범위가 모든 사람에게 미친다. 그리스도의 십자가는 보편적 가치를 지닌다"},
    {"원어": "μαρτύριον (마르튀리온)", "의미_문법": "증거 - 명사 중성 단수 주격. 증언, 증거", "설교포인트": "그리스도의 대속은 때가 이르러 증거로 선포되었다. 역사적 사건이며 증거되어야 할 진리이다"}
