    {"항목": "여성의 가정 소명", "내용": "1세기 기독교는 여성의 가정 내 역할을 존귀하게 여겼다. 이는 여성을 가정에 국한시키려는 것이 아니라 가정을 포함한 모든 영역에서의 소명을 존중한 것이다", "목회적활용": "가정은 작은 교회이며 어머니의 사역은 하나님 나라의 중요한 영역이다"}
