    {"원어": "βαθμὸν καλὸν (바트몬 칼론)", "의미_문법": "아름다운 지위 - 명사 + 형용사 남성 단수 대격. 좋은 계단, 진급", "설교포인트": "바트모스는 계단의 한 층을 의미한다. 섬김은 더 높은 계단으로의 이동이다"},
    {"원어": "παρρησίαν (파르레시안)", "의미_문법": "담력 - 명사 여성 단수 대격. 대담한 말, 자유로운 확신", "설교포인트": "파르레시아는 공적 발언의 자유를 의미하는 정치적 용어이다. 충성된 섬김이 영적 담대함을 낳는다"}
