    {"구분": "룻의 나오미 돌봄", "내용": "룻은 시어머니 나오미를 끝까지 돌보았다. 가족의 경계를 초월한 돌봄이었다", "그리스도연결": "그리스도 안에서 새 가족 관계의 돌봄이 성립된다"}
